import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_ESCENA, MODELO_ESTUDIO, TABLA_ESCENAS } from '../../models/estudio-escena.model.mjs';

export async function buscarEstudioRepository(estudioId) {
  const { Item } = await MODELO_ESTUDIO.build(GetItemCommand)
    .key({ estudioId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarEstudioRepository(estudioId, minimo) {
  const { Items = [] } = await TABLA_ESCENAS.build(QueryCommand)
    .entities(MODELO_ESCENA)
    .query({ index: 'PorEstudio', partition: estudioId })
    .options({ filters: { Escena: { attr: 'duracionSegundos', gte: minimo } } })
    .send();
  return Items;
}
